#include "game_session.h"
namespace cf {
void GameSession::configure(const Project &p,bool restart){project=p;initial.clear();for(auto &v:p.variables)initial<<int16_t(v.initial);limits.clear();for(auto &i:p.items)limits<<uint8_t(i.stackLimit);counts.resize(p.storages.size());stores.resize(p.storages.size());for(int s=0;s<p.storages.size();++s){counts[s].fill(0,p.items.size());for(auto i=p.storages[s].contents.begin();i!=p.storages[s].contents.end();++i){int index=p.itemIndex(i.key());if(index>=0)counts[s][index]=i.value();}stores[s]={uint8_t(p.storages[s].capacity),counts[s].data()};}definition={uint8_t(initial.size()),uint8_t(limits.size()),uint8_t(stores.size()),initial.data(),limits.data(),stores.data()};GameCompiler compiler(p);QString error;timerCode.resize(p.timers.size());timerDefs.resize(p.timers.size());for(int i=0;i<p.timers.size();++i){auto &t=p.timers[i];if(!compiler.program(t.source,timerCode[i],error))timerCode[i].clear();timerDefs[i]={uint16_t(t.interval),uint8_t(t.repeat),uint8_t(t.autostart),uint8_t(t.pauseDialogue),{uint8_t(timerCode[i].size()),timerCode[i].data()}};}definition.seed=p.rngSeed;definition.timer_count=timerDefs.size();definition.timers=timerDefs.data();prompts.fill({},p.prompts.size());rules.fill({},p.prompts.size()*3);enter.resize(p.prompts.size());enterCode.resize(p.prompts.size());choiceCode.resize(p.prompts.size()*3);
for(int i=0;i<p.prompts.size();++i){auto &prompt=p.prompts[i];prompts[i].choice_count=prompt.choices.size();if(!compiler.program(prompt.onEnter,enterCode[i],error))enterCode[i].clear();enter[i]={uint8_t(enterCode[i].size()),enterCode[i].data()};for(int c=0;c<prompt.choices.size();++c){int index=i*3+c;compiler.condition(prompt.choices[c].condition,rules[index].condition,error);if(!compiler.program(prompt.choices[c].actions,choiceCode[index],error))choiceCode[index].clear();rules[index].actions={uint8_t(choiceCode[index].size()),choiceCode[index].data()};int target=p.indexOf(prompt.choices[c].target);prompts[i].targets[c]=target<0?255:target;}}
if(restart)reset();}
void GameSession::reset(){cf_game_init(&state,&definition);}
void GameSession::enterPrompt(CFState &flow,int index){if(index>=0&&index<prompts.size()){cf_story_enter(&flow,index,&state,&definition,enter.data());cf_story_normalize(&flow,prompts.data(),rules.data(),&state);}}
bool GameSession::step(CFState &flow,int key){return cf_story_step(&flow,prompts.data(),prompts.size(),project.indexOf(project.entry),key,&state,&definition,rules.data(),enter.data());}
bool GameSession::enabled(int p,int c)const{return p>=0&&p<prompts.size()&&c>=0&&c<prompts[p].choice_count&&cf_game_condition(&state,&rules[p*3+c].condition);}
bool GameSession::run(const QString &source){QVector<CFInstruction> code;QString error;if(!GameCompiler(project).program(source,code,error))return false;CFProgram p{uint8_t(code.size()),code.data()};return cf_game_execute(&state,&definition,&p);}
}
